// seed-suppliers.js
//
// Loads supabase/seeds/glass-outlet/supplier-catalogue.json (generated by
// scripts/import-replica-supplier-items.mjs) and upserts:
//   1. suppliers        (keyed on org_id + slug)
//   2. supplier_items   (keyed on org_id + source_key, batched)
//   3. Backfills product_components.supplier_id → 'glass-outlet' for engine
//      components that have no supplier attribution yet (all pre-034 SKUs are
//      bought from The Glass Outlet).
//
// Usage: node supabase/seeds/tools/seed-suppliers.js   (or: npm run seed:suppliers)

import { createClient } from '@supabase/supabase-js';
import dotenv from 'dotenv';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

dotenv.config({ path: `.env.${process.env.NODE_ENV || 'local'}`, override: true });

const supabaseUrl = process.env.VITE_SUPABASE_URL;
const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!supabaseUrl) throw new Error('Missing VITE_SUPABASE_URL');
if (!serviceRoleKey) throw new Error('Missing SUPABASE_SERVICE_ROLE_KEY');

const supabase = createClient(supabaseUrl, serviceRoleKey, {
  auth: { persistSession: false },
});

const __dirname = dirname(fileURLToPath(import.meta.url));
const CATALOGUE_FILE = resolve(__dirname, '..', 'glass-outlet', 'supplier-catalogue.json');

const BATCH_SIZE = 500;

async function main() {
  const raw = JSON.parse(readFileSync(CATALOGUE_FILE, 'utf8'));

  const { data: org, error: orgErr } = await supabase
    .from('organisations')
    .select('id')
    .eq('slug', raw.org_slug)
    .maybeSingle();
  if (orgErr) throw new Error(`org lookup: ${orgErr.message}`);
  if (!org) throw new Error(`org not found: ${raw.org_slug}`);
  const orgId = org.id;

  // 1. suppliers
  const supplierRows = raw.suppliers.map((s) => ({
    org_id: orgId,
    name: s.name,
    slug: s.slug,
    active: s.active !== false,
    metadata: s.metadata ?? {},
  }));
  const { error: supErr } = await supabase
    .from('suppliers')
    .upsert(supplierRows, { onConflict: 'org_id,slug', ignoreDuplicates: false });
  if (supErr) throw new Error(`suppliers: ${supErr.message}`);
  console.log(`suppliers: ${supplierRows.length} upserted`);

  const { data: supplierIds, error: idErr } = await supabase
    .from('suppliers')
    .select('id, slug')
    .eq('org_id', orgId);
  if (idErr) throw new Error(`supplier id fetch: ${idErr.message}`);
  const idBySlug = new Map(supplierIds.map((s) => [s.slug, s.id]));

  // 2. supplier_items in batches
  let total = 0;
  for (let i = 0; i < raw.supplier_items.length; i += BATCH_SIZE) {
    const batch = raw.supplier_items.slice(i, i + BATCH_SIZE).map((it) => {
      const supplierId = idBySlug.get(it.supplier_slug);
      if (!supplierId) throw new Error(`unknown supplier_slug: ${it.supplier_slug}`);
      return {
        org_id: orgId,
        supplier_id: supplierId,
        sku: it.sku,
        description: it.description,
        category: it.category,
        system: it.system,
        colour: it.colour,
        material: it.material,
        unit: it.unit ?? 'each',
        price: it.price,
        source: it.source ?? null,
        source_key: it.source_key,
        imported_date: it.imported_date,
        active: it.active !== false,
        metadata: it.metadata ?? {},
      };
    });
    const { error } = await supabase
      .from('supplier_items')
      .upsert(batch, { onConflict: 'org_id,source_key', ignoreDuplicates: false });
    if (error) throw new Error(`supplier_items batch ${i / BATCH_SIZE + 1}: ${error.message}`);
    total += batch.length;
    console.log(`supplier_items: ${total}/${raw.supplier_items.length}`);
  }

  // 3. Backfill engine components with no supplier → Glass Outlet
  const glassOutletId = idBySlug.get('glass-outlet');
  if (glassOutletId) {
    const { error: backfillErr, count } = await supabase
      .from('product_components')
      .update({ supplier_id: glassOutletId }, { count: 'exact' })
      .eq('org_id', orgId)
      .is('supplier_id', null);
    if (backfillErr) throw new Error(`component backfill: ${backfillErr.message}`);
    console.log(`product_components backfilled to glass-outlet: ${count ?? 'ok'}`);
  }

  console.log('\nSeed suppliers done.');
}

main().catch((e) => {
  console.error('\nSEED SUPPLIERS FAILED:', e.message);
  process.exit(1);
});
